// Builds each tool's generated files from the factory's sources. generate.ts writes them, and
// --check compares them with what's on disk. Factory ADRs 0021 and 0032 describe what each tool gets,
// and 0033 describes when a tool gets agent files at all.
import { posix } from "node:path";
import { DENIED_PATTERNS, groupCommands, prefixPatterns } from "./commands";
import { FactoryError, MODEL_CLASSES, TOOLS } from "./factory";
import type { Agent, Factory, ModelClass, ToolModels, ToolName } from "./factory";
import { looseScope } from "./scopes";
import type { Scope } from "./scopes";

export const GENERATOR = "bun chrysalis/scripts/generate.ts";

/** Folders that hold only generated agent files. The generator deletes anything else in them. */
export const AGENT_DIRS: Record<ToolName, string> = {
  cursor: ".cursor/agents",
  kilo: ".kilo/agents",
  kiro: ".kiro/agents",
  claude: ".claude/agents",
};

/** Generated files for a whole tool, written whatever its models, because they deny commands to every agent. */
export const KIRO_HOOK = ".kiro/hooks/chrysalis-deny-commands.json";
export const CLAUDE_SETTINGS = ".claude/settings.json";

const DENY_HOOK_SCRIPT = "chrysalis/scripts/hooks/deny-commands.ts";
const WRITE_HOOK_SCRIPT = "chrysalis/scripts/hooks/write-scope.ts";

export type Plan = {
  /** Each generated file's path from the repository root, and its content. */
  files: Map<string, string>;
  /** One line per tool on what the generator wrote for it, or why it wrote no agent files. */
  notes: string[];
};

// ---- Models ----

/** The confirmed model ID for a class: the model, or else its confirmed fallback. */
function confirmedModel(tool: ToolModels, cls: ModelClass): string | null {
  const entry = tool.classes[cls];
  if (entry.confirmed) return entry.model;
  if (entry.fallback && entry.fallback_confirmed) return entry.fallback;
  return null;
}

/**
 * The model ID for each class, when every class has a confirmed one. Null when none does, so the
 * tool gets no agent files. Some but not all is an error, because the classes must differ as a set.
 */
function toolModels(name: ToolName, tool: ToolModels | undefined): Record<ModelClass, string> | null {
  if (!tool) return null;
  const picked = MODEL_CLASSES.map((cls) => [cls, confirmedModel(tool, cls)] as const);
  const missing = picked.filter(([, id]) => id === null).map(([cls]) => cls);
  if (missing.length === MODEL_CLASSES.length) return null;
  if (missing.length) {
    throw new FactoryError([
      `chrysalis/models.yaml confirms a model for some of ${name}'s classes but not for ${missing.join(", ")}. ` +
        "Confirm all four classes for a tool, or none, so its gate agents never run on an unchecked model.",
    ]);
  }
  return Object.fromEntries(picked) as Record<ModelClass, string>;
}

// ---- Text helpers ----

function yamlKey(key: string): string {
  return /^[A-Za-z_][A-Za-z0-9_-]*$/.test(key) ? key : JSON.stringify(key);
}

/** A small YAML writer for frontmatter: maps, lists of strings, strings, and booleans. */
function yaml(value: unknown, indent = ""): string[] {
  const lines: string[] = [];
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (Array.isArray(item)) {
      lines.push(`${indent}${yamlKey(key)}:`);
      for (const entry of item) lines.push(`${indent}  - ${JSON.stringify(entry)}`);
    } else if (typeof item === "object" && item !== null) {
      lines.push(`${indent}${yamlKey(key)}:`, ...yaml(item, `${indent}  `));
    } else {
      lines.push(`${indent}${yamlKey(key)}: ${typeof item === "string" ? JSON.stringify(item) : String(item)}`);
    }
  }
  return lines;
}

function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}

/**
 * Rewrites each relative Markdown link in an agent file's body to a path from the repository root,
 * because the copy lives in another folder and agents read paths from the root.
 */
export function rewriteLinks(body: string, sourceFile: string): string {
  const dir = posix.dirname(sourceFile);
  return body.replace(/\]\(([^)\s]+)\)/g, (whole, target: string) => {
    if (/^(?:[a-z][a-z0-9+.-]*:|#|\/)/i.test(target)) return whole;
    const hash = target.indexOf("#");
    const path = hash < 0 ? target : target.slice(0, hash);
    const anchor = hash < 0 ? "" : target.slice(hash);
    return `](${posix.normalize(posix.join(dir, path))}${anchor})`;
  });
}

/** The prompt for tools that can't point at the agent file: a header, then a copy of its body. */
function copiedBody(agent: Agent): string {
  return [
    `<!-- Generated by ${GENERATOR} from ${agent.file}. Edit that file, then run the generator again. -->`,
    "",
    `This prompt copies the body of \`${agent.file}\`. Read that file's frontmatter for your write scope, shell command groups, and skills, and read each skill it lists before you start. Paths in links are from the repository root.`,
    "",
    rewriteLinks(agent.body, agent.file),
    "",
  ].join("\n");
}

function markdown(frontmatter: Record<string, unknown>, body: string): string {
  return ["---", ...yaml(frontmatter), "---", "", body].join("\n");
}

// ---- One renderer per tool ----

type Context = { factory: Factory; models: Record<ModelClass, string> };

function scopeOf(agent: Agent, factory: Factory): Scope {
  return looseScope(agent.write_scope, factory.stacks);
}

function allowedCommands(agent: Agent, factory: Factory): string[] {
  return prefixPatterns(groupCommands(agent.shell, factory.stacks));
}

/** Cursor offers only a model and a read-only flag. Gate agents stay writable so they can post verdicts. See ADR 0032. */
function cursorAgent(agent: Agent, { models }: Context): string {
  return markdown({ name: agent.name, description: agent.description, model: models[agent.model_class] }, copiedBody(agent));
}

/**
 * Kilo's last matching rule wins, so the catch-all rules come first. Its * also matches /, so no
 * pattern means "files directly in the root", and an agent whose scope includes them may edit anything.
 */
function kiloAgent(agent: Agent, { factory, models }: Context): string {
  const scope = scopeOf(agent, factory);
  const edit = scope.rootFiles ? "allow" : scope.globs.length ? Object.fromEntries([["*", "deny"], ...scope.globs.map((glob) => [glob, "allow"])]) : "deny";
  const bash = Object.fromEntries([
    ["*", "ask"],
    ...allowedCommands(agent, factory).map((pattern) => [pattern, "allow"]),
    ...DENIED_PATTERNS.map((pattern) => [pattern, "deny"]),
  ]);
  const frontmatter: Record<string, unknown> = { description: agent.description, mode: agent.mode, model: models[agent.model_class] };
  // The human talks only to the TPM, so subagents stay out of Kilo's @ menu. See ADR 0032.
  if (agent.mode === "subagent") frontmatter.hidden = true;
  frontmatter.permission = { edit, bash };
  return markdown(frontmatter, copiedBody(agent));
}

/**
 * Kiro asks about a write that no rule matches, so a deny rule covers every path outside the scope.
 * A deny wins over every allow, in any scope. The prompt points at the agent file. See ADR 0032.
 */
function kiroAgent(agent: Agent, { factory, models }: Context): string {
  const scope = scopeOf(agent, factory);
  const globs = scope.rootFiles ? [...scope.globs, "*", ".*"] : scope.globs;
  const tools = ["read", "shell", "web"];
  if (globs.length) tools.splice(1, 0, "write");
  if (agent.mode === "primary") tools.push("subagent");
  const rules: Record<string, unknown>[] = [];
  rules.push(globs.length ? { capability: "fs_write", match: ["**"], exclude: globs, effect: "deny" } : { capability: "fs_write", match: ["**"], effect: "deny" });
  if (globs.length) rules.push({ capability: "fs_write", match: globs, effect: "allow" });
  const allowed = allowedCommands(agent, factory);
  if (allowed.length) rules.push({ capability: "shell", match: allowed, effect: "allow" });
  rules.push({ capability: "shell", match: DENIED_PATTERNS, effect: "deny" });
  return json({
    name: agent.name,
    description: agent.description,
    prompt: `file://${posix.relative(AGENT_DIRS.kiro, agent.file)}`,
    model: models[agent.model_class],
    tools,
    permissions: { rules },
  });
}

/** Claude Code can't point a subagent at another file, so it gets a copy of the body. Its write hook is in settings.json. */
function claudeAgent(agent: Agent, { models }: Context): string {
  const frontmatter: Record<string, unknown> = { name: agent.name, description: agent.description, model: models[agent.model_class] };
  if (!agent.write_scope.length) frontmatter.disallowedTools = "Edit, Write, NotebookEdit";
  return markdown(frontmatter, copiedBody(agent));
}

const RENDERERS: Record<ToolName, { ext: string; render: (agent: Agent, ctx: Context) => string }> = {
  cursor: { ext: ".md", render: cursorAgent },
  kilo: { ext: ".md", render: kiloAgent },
  kiro: { ext: ".json", render: kiroAgent },
  claude: { ext: ".md", render: claudeAgent },
};

// ---- Files for a whole tool ----

/** Kiro runs the hook before every shell command, in the project root. A failed hook blocks the command. */
function kiroHook(): string {
  return json({
    version: "v1",
    hooks: [
      {
        name: "Chrysalis: deny pull request, merge, and history-rewriting commands",
        description: `Generated by ${GENERATOR}. Blocks the commands chrysalis/templates/agent.md denies to every agent.`,
        trigger: "PreToolUse",
        matcher: "shell",
        action: { type: "command", command: `bun ${DENY_HOOK_SCRIPT}` },
        timeout: 30,
      },
    ],
  });
}

/** Claude Code's deny rules and hooks apply to the main session and to every subagent. */
function claudeSettings(): string {
  const hook = (script: string) => ({ type: "command", command: `bun "$CLAUDE_PROJECT_DIR/${script}"` });
  return json({
    $schema: "https://json.schemastore.org/claude-code-settings.json",
    permissions: { deny: DENIED_PATTERNS.map((pattern) => `Bash(${pattern})`) },
    hooks: {
      PreToolUse: [
        { matcher: "Bash", hooks: [hook(DENY_HOOK_SCRIPT)] },
        { matcher: "Edit|Write|MultiEdit|NotebookEdit", hooks: [hook(WRITE_HOOK_SCRIPT)] },
      ],
    },
  });
}

/** Every file the generator owns, with its content. Throws a FactoryError when the models can't be used. */
export function planFiles(factory: Factory): Plan {
  const files = new Map<string, string>();
  const notes: string[] = [];
  const problems: string[] = [];
  for (const name of TOOLS) {
    let models: Record<ModelClass, string> | null;
    try {
      models = toolModels(name, factory.models[name]);
    } catch (error) {
      problems.push(...(error as FactoryError).problems);
      continue;
    }
    if (!models) {
      notes.push(`${name}: no agent files, because chrysalis/models.yaml confirms no model for it.`);
      continue;
    }
    const { ext, render } = RENDERERS[name];
    for (const agent of factory.agents) files.set(`${AGENT_DIRS[name]}/${agent.name}${ext}`, render(agent, { factory, models }));
    notes.push(`${name}: ${factory.agents.length} agent files in ${AGENT_DIRS[name]}/.`);
  }
  if (problems.length) throw new FactoryError(problems);
  files.set(KIRO_HOOK, kiroHook());
  files.set(CLAUDE_SETTINGS, claudeSettings());
  notes.push(`kiro: the deny hook in ${KIRO_HOOK}.`, `claude: the deny rules and hooks in ${CLAUDE_SETTINGS}.`);
  return { files, notes };
}
